"use strict";
const tg = window.Telegram?.WebApp;
tg?.ready();
tg?.expand();

const $ = (id) => document.getElementById(id);
let state = { items: [], categories: [], uid: 0, enabled: true, profiles: [], dates: [], prefs: null };
let page = 'home', cat = null, editing = null, month = new Date(), selectedDay = null, loading = false, showHiddenCategories = false, editingCategory = null, listOrigin = 'home';

const defaultCategoryColors = ['#8b6fbf','#f59eb1','#7d85e8','#7e96d9','#88c7d8','#f7b686','#a98fe0','#94c7a8'];
const defaultIcons = ['📋','🎁','🎬','📍','🛒','✈️','📅','💡'];

function node(tag, text, cls) {
  const e = document.createElement(tag);
  if (text !== undefined) e.textContent = text;
  if (cls) e.className = cls;
  return e;
}
function btn(text, fn, cls='secondary') {
  const b = node('button', text, cls);
  b.type = 'button';
  b.onclick = fn;
  return b;
}
function error(e) { $('error').textContent = e?.message || String(e); }

async function api(path, method='GET', body) {
  if(!tg?.initData)throw Error('Откройте приложение через Telegram с подключением к интернету');
  const r = await fetch(window.PLANNER_API + '/api/' + path, {
    method,
    headers: {
      'X-Telegram-Init-Data': tg?.initData || '',
      'Content-Type': 'application/json',
      'X-Planner-Generation': String(state.generation||'')
    },
    body: body === undefined ? undefined : JSON.stringify(body),
    cache: 'no-store'
  });
  let data = {};
  try { data = await r.json(); } catch {}
  if (!r.ok) {const e=Error(typeof data.detail==='string'?data.detail:'Проверьте введённые данные');e.status=r.status;throw e;}
  return data;
}
let refreshTask;
function refresh() {
  if (loading) return refreshTask;
  refreshTask=refreshNow(); return refreshTask;
}
async function refreshNow() {
  loading = true; document.body.classList.add('syncing');
  try {
    const next=await api('state'); if(state.generation&&next.generation&&state.generation!==next.generation){pendingWrites.clear();editorDrafts.clear();settingsTimers.forEach(t=>clearTimeout(t));settingsTimers.clear();for(const d of document.querySelectorAll('dialog[open]'))d.close();cat=null;layoutOverride=null;collapsedMemory.clear();settingsFailed={};go('home');try{for(const k of Object.keys(localStorage))if(k==='cats-layout-'+state.uid||k==='cats-haptic-'+state.uid||k.startsWith('cats-collapse-'+state.uid+'-'))localStorage.removeItem(k)}catch{}} if(vaultKey&&Number(next.uid)!==vaultUid){vaultKey=null;vaultUid=0;pendingWrites.clear();editorDrafts.clear()} const same=JSON.stringify(next)===JSON.stringify(state); state=next; void persistVault(); connectionState(pendingWrites.size?'Ожидают отправки: '+pendingWrites.size:''); $('error').textContent=''; if(same){updateUnread();return;}
    applyPrefs();
    if (!cat && state.categories.length) cat = visibleCategories()[0]?.id ?? state.categories[0].id;
    $('error').textContent = '';
    render();
    updateUnread();
  } catch (e) { error(e); if(e.status===401||e.status===403){vaultKey=null;vaultUid=0;state={items:[],categories:[],uid:0,enabled:false,profiles:[],dates:[],prefs:null};pendingWrites.clear();editorDrafts.clear();for(const d of document.querySelectorAll('dialog[open]'))d.close();go('home');connectionState('Откройте приложение через Telegram заново')}else{connectionState('Нет связи · показаны последние данные');if(!state.uid&&!e.status)void offerVaultUnlock()} }
  finally { loading = false; document.body.classList.remove('syncing'); }
}
async function mutate(path, method, body) {
  try {
    await api(path, method, body);
    if(loading) await refreshTask;
    await refresh();
    haptic(true);
    return true;
  } catch (e) {
    error(e);
    return false;
  }
}
function go(p) {
  if(p!==page){bulkMode=false;bulkSelected.clear();}
  const changed=page!==p;if(changed) scrollMemory.set(page,window.scrollY); page = p;
  for (const s of ['home','list','calendar','stats','more','searchPage']) $(s).hidden = s !== p;
  render();
  if(changed){window.scrollTo(0,scrollMemory.get(p)||0);haptic(false);}
}
function local(s) {
  return s ? new Date(s).toLocaleString('ru-RU', { dateStyle: 'medium', timeStyle: 'short' }) : '';
}
function localInput(s) {
  if (!s) return '';
  const d = new Date(s);
  return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
}
function daykey(d) { return `${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`; }
function hexToRgba(hex, alpha=0.22){
  const h = (hex||'#8b6fbf').replace('#','');
  const v = h.length===3 ? h.split('').map(x=>x+x).join('') : h;
  const n = parseInt(v,16);
  if (!Number.isFinite(n)) return `rgba(139,111,191,${alpha})`;
  const r=(n>>16)&255, g=(n>>8)&255, b=n&255;
  return `rgba(${r},${g},${b},${alpha})`;
}
function sortedCategories() {
  return [...state.categories].sort((a,b)=> (a.sort_order ?? 0) - (b.sort_order ?? 0) || a.id - b.id);
}
function visibleCategories() {
  return sortedCategories().filter(c => categoryType(c)!=='calendar'||c.wishlist_owner||state.items.some(r=>r.category===c.id&&!r.due)).filter(c=>showHiddenCategories||!c.archived);
}
function categoryType(c){return c?.wishlist_owner?'wish':c?.system_type||({'Наши дела':'task','Что посмотреть':'movie','Куда сходить':'place','Покупки':'shopping','Путешествия':'travel','Календарь':'calendar','Наши идеи':'idea'}[c?.name]||'custom')}
