function renderPet(){const e=$('petDetail');e.replaceChildren();const p=state.pet;if(!p)return;const act=async(action,arg='')=>{if(await coupleMutate('pet','PUT',{action,arg}))renderPet()};const hero=sectionCard(p.name+' · Ур. '+(1+Math.floor(p.xp/100)));hero.classList.add('stable-pet-hero');hero.append(petArt(p),node('p','🪙 '+p.coins+' · Опыт '+p.xp));for(const [label,key] of [['🍗 Сытость','hunger'],['💕 Настроение','mood'],['⚡ Энергия','energy']]){const row=node('div',undefined,'stable-pet-meter');row.append(node('span',label),node('small',p[key]+'%'));const bar=node('progress');bar.max=100;bar.value=p[key];row.append(bar);hero.append(row)}const actions=node('div',undefined,'actions');actions.append(btn('🍗 Кормить (10)',()=>act('feed')),btn('💕 Гладить',()=>act('pet')),btn('💤 Спать',()=>act('sleep')));hero.append(actions,btn('Изменить имя',async()=>{const name=await glassText('Имя питомца',p.name);if(name?.trim())act('name',name.trim())},'secondary wide'),btn(p.kind==='cat'?'Выбрать лисичку':'Выбрать котика',()=>act('kind',p.kind==='cat'?'fox':'cat'),'secondary wide'));e.append(hero,node('h3','Магазин'));const store=node('div',undefined,'stable-shop');e.append(store);for(const [k,[icon,title,price]] of Object.entries(shop)){const c=sectionCard(icon+' '+title),owned=(p.owned||[]).includes(k);c.append(node('p',owned?'Куплено':price+' монет','meta'));const b=btn(p.equipped===k?'Снять':owned?'Надеть':'Купить',async()=>{if(owned||await glassConfirm('Купить за '+price+' монет?'))act(owned?'equip':'buy',p.equipped===k?'':k)},'secondary wide');b.disabled=!owned&&p.coins<price;c.append(b);store.append(c)}e.append(node('p','Питомец не умирает и не теряет опыт. Показатели постепенно снижаются, но не ниже 45%; за пропущенные дни штрафов нет.','meta'))};$('closePet').onclick=()=>$('petDialog').close();
function renderAch(){const e=$('achRows');e.replaceChildren();const all=(state.achievements||[]).filter(a=>achInfo[a.code]);const header=sectionCard('Наши достижения');header.append(node('strong',all.filter(a=>a.unlocked).length+' из '+all.length));e.append(header);const group=node('div',undefined,'stable-ach-group');e.append(group);for(const a of all){const info=achInfo[a.code];if(!info)continue;const c=sectionCard((a.unlocked?info[0]:'🔒')+' '+info[1]);c.append(node('p',info[2]),node('p',a.unlocked?'Открыто · '+local(a.unlocked):Math.min(a.progress,a.target)+'/'+a.target,'meta'));const p=node('progress');p.max=a.target;p.value=a.unlocked?a.target:Math.min(a.progress,a.target);c.append(p);group.append(c)}}function openAch(){renderAch();if(!$('achDialog').open)$('achDialog').showModal()};$('closeAch').onclick=()=>$('achDialog').close();
let widgetEdit=[];function drawWidgetOrder(){const e=$('widgetOrder');e.replaceChildren();for(let i=0;i<widgetEdit.length;i++){const w=widgetEdit[i],row=node('div',undefined,'widget-setting'),label=node('label',undefined,'check'),input=node('input');input.type='checkbox';input.checked=w.enabled;input.onchange=()=>w.enabled=input.checked;label.append(input,node('span',widgets[w.key][1]));row.append(label,btn('↑',()=>{if(i){[widgetEdit[i-1],widgetEdit[i]]=[widgetEdit[i],widgetEdit[i-1]];drawWidgetOrder()}}),btn('↓',()=>{if(i<widgetEdit.length-1){[widgetEdit[i+1],widgetEdit[i]]=[widgetEdit[i],widgetEdit[i+1]];drawWidgetOrder()}}));e.append(row)}}
function toTime(n){return n==null?'':String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}function fromTime(s){return s?Number(s.slice(0,2))*60+Number(s.slice(3)):null}
function openCoupleSettings(){const p=state.prefs||{},order=(p.home_widgets??widgetDefaults).filter(k=>Object.hasOwn(widgets,k));widgetEdit=[...order,...widgetDefaults.filter(k=>!order.includes(k))].map(key=>({key,enabled:order.includes(key)}));drawWidgetOrder();const v=$('coupleForm').elements;v.tone.value=p.tone||'care';for(const k of ['notify_reminders','notify_updates'])v[k].checked=p[k]!==false;v.quiet_start.value=toTime(p.quiet_start);v.quiet_end.value=toTime(p.quiet_end);$('coupleDialog').showModal()};$('coupleSettings').onclick=openCoupleSettings;$('closeCoupleSettings').onclick=()=>$('coupleDialog').close();$('coupleForm').onsubmit=async e=>{e.preventDefault();const v=e.target.elements;if(!!v.quiet_start.value!==!!v.quiet_end.value){showMessage('Укажи обе границы тихих часов или очисти обе');return}if(await coupleMutate('profile','PUT',{home_widgets:widgetEdit.filter(w=>w.enabled).map(w=>w.key),tone:v.tone.value,notify_reminders:v.notify_reminders.checked,notify_updates:v.notify_updates.checked,quiet_start:fromTime(v.quiet_start.value),quiet_end:fromTime(v.quiet_end.value),tz:Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC'}))$('coupleDialog').close()};

function renderTaxonomy(c){const rows=itemsInCat(c.id),subs=[...new Set(rows.map(r=>r.subcategory).filter(Boolean))].sort(),tags=[...new Set(rows.flatMap(r=>r.tags||[]))].sort();for(const [id,values,label] of [['subFilter',subs,'Все подкатегории'],['tagFilter',tags,'Все теги']]){const s=$(id),old=s.value;s.replaceChildren(...['',...values].map(v=>{const o=node('option',v||label);o.value=v;return o}));s.value=values.includes(old)?old:'';s.hidden=!values.length}$('taxonomyFilters').hidden=!subs.length&&!tags.length}
