function drawNav(){const e=$('navEditor');e.replaceChildren();navDraft.forEach((x,i)=>{const r=node('div',undefined,'widget-setting'),l=node('label',undefined,'check'),b=node('input');b.type='checkbox';b.checked=x.on;b.disabled=['home','more'].includes(x.key);b.onchange=()=>x.on=b.checked;l.append(b,node('span',navLabels[x.key][1]));r.append(l,btn('↑',()=>{if(i){[navDraft[i-1],navDraft[i]]=[navDraft[i],navDraft[i-1]];drawNav()}}),btn('↓',()=>{if(i<navDraft.length-1){[navDraft[i],navDraft[i+1]]=[navDraft[i+1],navDraft[i]];drawNav()}}));e.append(r)})}
function loadStyleForm(){const p=state.prefs||{},v=$('profileForm').elements;bgData=p.background||null;preview('backgroundPreview','removeBackground',bgData);v.corner.value=p.corner??20;v.compact.checked=!!p.compact;v.card_size.value=p.card_size||'normal';const a=p.nav_pages||['home','calendar','stats','more'];navDraft=[...a,...Object.keys(navLabels).filter(k=>!a.includes(k))].map(key=>({key,on:a.includes(key)}));drawNav()}
function stylePayload(){const v=$('profileForm').elements;return {background:bgData,corner:Number(v.corner.value),compact:v.compact.checked,card_size:v.card_size.value,nav_pages:navDraft.filter(x=>x.on).map(x=>x.key)}}
function applyStyle(p){const root=document.documentElement;root.style.setProperty('--corner',(p.corner??20)+'px');document.body.dataset.compact=String(!!p.compact);document.body.dataset.cardSize=p.card_size||'normal';const sky=document.querySelector('.sky');sky.style.backgroundImage=p.background?`url("${p.background}")`:'';document.body.classList.toggle('custom-bg',!!p.background);const nav=document.querySelector('nav');nav.replaceChildren(...(p.nav_pages||['home','calendar','stats','more']).filter(k=>k!=='search').map(k=>{const b=btn(navLabels[k][0],()=>go(k==='search'?'searchPage':k));b.dataset.page=k;b.replaceChildren();const cap=node('div',undefined,'nav-cap');cap.append(lineIcon(k));b.append(cap,node('span',navLabels[k][1]));b.setAttribute('aria-label',navLabels[k][1]);return b}))}
bindPhoto('backgroundFile','profileForm',v=>{bgData=v;preview('backgroundPreview','removeBackground',v)});$('removeBackground').onclick=()=>{bgData=null;preview('backgroundPreview','removeBackground',null)};
function addCheckRow(x={text:'',done:false}){const r=node('div',undefined,'check-edit'),c=node('input'),t=node('input');c.type='checkbox';c.checked=x.done;t.value=x.text;t.maxLength=200;t.placeholder='Подзадача';r.append(c,t,btn('×',()=>r.remove()));$('checkEditor').append(r)}
function drawChecklist(rows){$('checkEditor').replaceChildren();rows.forEach(addCheckRow)}
function readChecklist(){return [...$('checkEditor').children].map(r=>({text:r.children[1].value.trim(),done:r.children[0].checked})).filter(x=>x.text)}
$('addCheck').onclick=()=>{if($('checkEditor').children.length<50)addCheckRow()};
function matchText(r,q){return [r.title,r.notes,r.link,r.subcategory,...(r.tags||[]),...(r.checklist||[]).map(x=>x.text),catById(r.category)?categoryName(catById(r.category)):''].join(' ').toLowerCase().replaceAll('ё','е').includes(q.trim().toLowerCase().replaceAll('ё','е'))}
function renderGlobal(){const q=$('globalSearch').value.trim(),root=$('globalRows');const rows=q?[...state.items,...(state.archivedItems||[])].filter(r=>matchText(r,q)):[];root.replaceChildren(...(rows.length?rows.map(r=>r.archived_at?archiveCard(r,'archive'):entry(r)):[node('p',q?'Ничего не найдено':'Введите запрос','meta')]))}
$('globalSearch').oninput=renderGlobal;
function archiveCard(r,mode){const e=sectionCard((mode==='archive'?'📦 ':'🗑️ ')+r.title);e.classList.add('library-record');e.append(node('p',categoryName(catById(r.category)||{name:'Категория'})+' · '+local(r.deleted_at||r.archived_at),'meta'));if(r.notes)e.append(node('p',r.notes));e.append(btn('Восстановить',()=>life(r,mode==='archive'?'unarchive':'restore'),'secondary wide'));if(mode==='archive')e.append(btn('В корзину',async()=>{if(await glassConfirm('Переместить в корзину?'))life(r,'trash')},'danger-soft wide'));return e}
let libraryMode='';async function life(r,action){if(await mutate('items/'+r.id+'/lifecycle','PUT',{action,version:r.version})){if(action==='archive'||action==='trash')offerUndo(r.id,action);if($('libraryDialog').open)openLibrary(libraryMode)}else showMessage($('error').textContent)}
const inboxLogo = 'data:image/jpeg;base64,';
function inboxGreeting(r){return r.body==="🐱 Cat's planner — ваши общие планы и желания."}
function inboxParts(body){const text=String(body||'');const m=text.match(/^(?:[\p{Extended_Pictographic}\uFE0F\u200D]+\s*)?(Обновление[^:]*|Добавлена запись|Выполнено|Изменена запись|Возвращено в планы|Удалена запись|В корзину|В архив|Восстановлено|Возвращено из архива|Новый комментарий|Добавлена важная дата):\s*(.*)$/u);return m?{kind:m[1],detail:m[2]}:{kind:'Уведомление',detail:text};}
async function inboxAction(path,method,body){try{await api(path,method,body);haptic(true);await updateUnread();if(libraryMode==='inbox'&&$('libraryDialog').open)await openLibrary('inbox')}catch(e){showMessage(e.message)}}
function inboxRecord(r){const parts=inboxParts(r.body), e=node('article',undefined,'library-record inbox-record');const img=node('img',undefined,'inbox-avatar');img.src=inboxLogo;img.alt='';const content=node('div',undefined,'inbox-content');const head=node('div',undefined,'inbox-head');head.append(node('strong',"Cat’s Planner"));if(!r.read_at){const dot=node('span',undefined,'inbox-dot');dot.setAttribute('aria-label','Новое');head.append(dot)}content.append(head,node('div',parts.kind,'inbox-kind'),node('p',parts.detail,'inbox-detail'),node('small',local(r.created_at),'inbox-time'));const action=btn('',()=>inboxAction('inbox/'+r.id,r.read_at?'DELETE':'PUT',r.read_at?undefined:{}),'secondary inbox-action');action.append(lineIcon(r.read_at?'trash':'check'));action.setAttribute('aria-label',r.read_at?'Удалить прочитанное уведомление':'Отметить прочитанным');action.title=action.getAttribute('aria-label');e.append(img,content,action);return e}
async function openLibrary(mode){libraryMode=mode;const root=$('libraryRows');$('libraryTitle').textContent=({archive:'Архив',trash:'Корзина',history:'История изменений',inbox:'Уведомления'})[mode];root.replaceChildren(node('p','Загрузка…','meta'));if(!$('libraryDialog').open)$('libraryDialog').showModal();try{if(mode==='archive'||mode==='trash'){const rows=mode==='archive'?state.archivedItems:state.trashItems;root.replaceChildren();for(const r of rows||[])root.append(archiveCard(r,mode))}else{const data=await api(mode);if(libraryMode!==mode||!$('libraryDialog').open)return;root.replaceChildren();const rows=mode==='inbox'?data.rows.filter(r=>!inboxGreeting(r)):data.rows;if(mode==='inbox'){const toolbar=node('div',undefined,'inbox-toolbar');if(rows.some(r=>!r.read_at))toolbar.append(btn('Прочитать все',()=>inboxAction('inbox','PUT',{}),'secondary'));if(rows.some(r=>r.read_at))toolbar.append(btn('Удалить прочитанные',async()=>{if(await glassConfirm('Удалить все прочитанные уведомления?'))inboxAction('inbox','DELETE')},'secondary'));if(toolbar.children.length)root.append(toolbar);for(const r of rows)root.append(inboxRecord(r))}else for(const r of rows){const e=sectionCard(r.title);e.classList.add('library-record');e.append(node('p',r.action+' · '+(r.actor?person(r.actor):'Система')+' · '+local(r.created_at),'meta'));root.append(e)}if(!rows.length)root.append(node('p',mode==='inbox'?'Пока нет уведомлений':'Пока пусто','meta'))}if(!root.children.length)root.append(node('p','Пока пусто','meta'))}catch(e){root.replaceChildren(node('p',e.message))}}

$('closeLibrary').onclick=()=>$('libraryDialog').close();
