function bindLongPress(el,action){let timer=null,start=null,fired=false;const cancel=()=>{clearTimeout(timer);timer=null;start=null};el.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'||!e.isPrimary)return;fired=false;start=[e.clientX,e.clientY];timer=setTimeout(()=>{timer=null;fired=true;haptic(false);action()},550)});el.addEventListener('pointermove',e=>{if(start&&Math.hypot(e.clientX-start[0],e.clientY-start[1])>10)cancel()});for(const k of ['pointerup','pointercancel','pointerleave'])el.addEventListener(k,cancel);el.addEventListener('contextmenu',e=>{if(e.pointerType==='touch'||fired)e.preventDefault()});el.addEventListener('click',e=>{if(fired){e.preventDefault();e.stopImmediatePropagation();fired=false}},true)}
function bindEntrySwipe(el,r){let start=null,dx=0,locked=false;const reset=()=>{el.style.transform='';el.classList.remove('swiping');start=null;dx=0;locked=false};el.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'||!e.isPrimary||e.target.closest('button,input,textarea,select,a,label,summary'))return;start=[e.clientX,e.clientY];dx=0});el.addEventListener('pointermove',e=>{if(!start)return;dx=e.clientX-start[0];const dy=e.clientY-start[1];if(!locked&&Math.abs(dy)>12&&Math.abs(dy)>Math.abs(dx)){reset();return}if(Math.abs(dx)>18&&Math.abs(dx)>Math.abs(dy)*1.5){locked=true;el.classList.add('swiping');el.style.transform=`translateX(${Math.max(-70,Math.min(70,dx*.45))}px)`}});el.addEventListener('pointercancel',reset);el.addEventListener('pointerup',async()=>{const d=dx,ok=locked;reset();if(!ok||Math.abs(d)<75)return;haptic(false);if(d>0){if(await glassConfirm(r.done?'Вернуть запись в активные?':'Отметить запись выполненной?'))mutate('items/'+r.id,'PUT',{...r,done:!r.done,private:!!r.private})}else if(await glassConfirm('Переместить запись в архив?'))life(r,'archive')})}
